import torch


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    dtype = getattr(torch, ctx["x__dtype"])
    base = torch.empty(shape, device=device, dtype=torch.float32).uniform_(-4.0, 4.0)
    x = torch.sigmoid(base).to(dtype=dtype)
    return {"x": x}


def run(x, eps):
    return torch.logit(x, eps=eps)


def run_correctness(x, eps):
    return torch.logit(x.float(), eps=eps).to(x.dtype)
